class TaskManager:
    """Manages an in-memory collection of tasks."""

    def count_tasks(self, completed: bool | None = None, tag: str | None = None) -> int:
        """Count tasks based on completion status and/or tag.

        Args:
            completed (bool | None): If True, count only completed tasks; if False, count only incomplete tasks; if None, count all tasks.
            tag (str | None): If provided, count only tasks with this tag.

        Returns:
            int: The number of tasks matching the criteria.
        """
        tasks = self._tasks.values()
        if completed is not None:
            tasks = [t for t in tasks if t.completed == completed]
        if tag is not None:
            tasks = [t for t in tasks if tag in t.tags]
        return len(tasks)
